// Word Replacement Engine
// Reads replacement_rules from the webhook payload (injected by Python bot)
const rules = $json.replacement_rules || [];

function applyReplacements(text, rules) {
  if (!text || typeof text !== 'string') return text;
  let result = text;
  for (const rule of rules) {
    if (!rule || !rule.pattern) continue;
    const pattern = rule.pattern;
    const replacement = rule.replacement || '';
    if (rule.is_regex) {
      try {
        result = result.replace(new RegExp(pattern, 'gm'), replacement);
      } catch (e) {
        // Ignore invalid regex patterns
      }
    } else {
      result = result.split(pattern).join(replacement);
    }
  }
  return result;
}

const data = {...$json};
if (data.text) {
  data.processed_text = applyReplacements(data.text, rules);
  data.text_changed = data.processed_text !== data.text;
}
if (data.caption) {
  data.processed_caption = applyReplacements(data.caption, rules);
  data.caption_changed = data.processed_caption !== data.caption;
}
return [{json: data}];

// Word Replacement (Album)
const rules = $json.replacement_rules || [];

function applyReplacements(text, rules) {
  if (!text || typeof text !== 'string') return text;
  let result = text;
  for (const rule of rules) {
    if (!rule || !rule.pattern) continue;
    const pattern = rule.pattern;
    const replacement = rule.replacement || '';
    if (rule.is_regex) {
      try {
        result = result.replace(new RegExp(pattern, 'gm'), replacement);
      } catch (e) {
        // Ignore invalid regex patterns
      }
    } else {
      result = result.split(pattern).join(replacement);
    }
  }
  return result;
}

const data = {...$json};
data.any_caption_changed = false;
if (data.items && Array.isArray(data.items)) {
  for (let item of data.items) {
    if (item.caption) {
      item.processed_caption = applyReplacements(item.caption, rules);
      if (item.processed_caption !== item.caption) {
        data.any_caption_changed = true;
      }
    }
  }
}
return [{json: data}];

// Route to all destinations (from payload)
const destinations = $json.destinations || [];
const results = [];
for (const dest of destinations) {
  results.push({
    json: {
      ...$json,
      destination_chat_id: dest.chat_id,
      destination_name: dest.name,
    }
  });
}
if (results.length === 0) {
  throw new Error('No destinations found in payload');
}
return results;

// Route to destinations (Media)
const destinations = $json.destinations || [];
const results = [];
for (const dest of destinations) {
