    json: {
      ...$json,
      destination_chat_id: dest.chat_id,
      destination_name: dest.name,
    }
  });
}
if (results.length === 0) {
  throw new Error('No destinations found in payload');
}
return results;

// Album Handler — route each item to each destination
const destinations = $json.destinations || [];
const items = $json.items || [];
const botToken = $json._bot_token || '';
const results = [];
for (const dest of destinations) {
  for (const item of items) {
    results.push({
      json: {
        chat_id: item.chat_id,
        message_id: item.message_id,
        destination_chat_id: dest.chat_id,
        destination_name: dest.name,
        caption: item.processed_caption || item.caption || '',
        media_group_id: $json.media_group_id,
        _bot_token: botToken,
      }
    });
  }
}
if (results.length === 0) {
  throw new Error('No destinations or items found');
}
return results;
